Method.Source:
/// <summary>
/// When an attribute on updated, this method will update the METCustTable to trigger the data event for do
/// </summary>
/// <param name="sender"></param>
/// <param name="e"></param>
[DataEventHandler(tableStr(EcoResBooleanValue), DataEventType::Updated)]
public static void EcoResBooleanValue_onUpdated(Common sender, DataEventArgs e)
{
    EcoResBooleanValue ecoResBooleanValue = sender as EcoResBooleanValue;

    EcoResBooleanValueTable_EventHandler::metUpdateMETCustTable(ecoResBooleanValue);
}

/// <summary>
/// When an attribute is  updated, this method will update the METCustTable to trigger the data event for downstream system to consume.
/// </summary>
public static void metUpdateMETCustTable(EcoResBooleanValue _ecoResBooleanValue)
{
    if (!_ecoResBooleanValue)
    {
        return;
    }

    METCustTable metCustTable;
    CustTable custTable;
    CustomerInstanceValue customerInstanceValue;
    EcoResAttributeValue ecoResAttributeValue;

    ttsbegin;

    select firstonly forupdate metCustTable
    exists join custTable
        where custTable.AccountNum == metCustTable.AccountNum
    exists join customerInstanceValue
        where customerInstanceValue.AccountNum == custTable.AccountNum
    exists join ecoResAttributeValue
        where ecoResAttributeValue.InstanceValue == customerInstanceValue.RecId
           && ecoResAttributeValue.Value == _ecoResBooleanValue.RecId;

    if (metCustTable)
    {
        metCustTable.DataEventDateTime = DateTimeUtil::utcNow();
        metCustTable.update();
    }

    ttscommit;
}
